import{_ as i,a0 as s,w as l,s as d,I as o,x as e,a1 as a,A as p,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"如何在 Fedora 上生成 EPUB 電子書 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora 上生成 EPUB 電子書 | LCTT (202006) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora 上生成 EPUB 電子書 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora 上生成 EPUB 電子書 | LCTT (202006) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202006/20200604 How to generate an EPUB file on Fedora","title":"如何在 Fedora 上生成 EPUB 電子書","tag":"202006","desc":""},"relativePath":"202006/20200604 How to generate an EPUB file on Fedora.md","filePath":"[post].md"}'),g={name:"202006/20200604 How to generate an EPUB file on Fedora.md"};function u(f,t,b,m,w,T){const r=s("Link");return l(),d("div",null,[t[29]||(t[29]=o("h1",{id:"如何在-fedora-上生成-epub-電子書",tabindex:"-1"},[e("如何在 Fedora 上生成 EPUB 電子書 "),o("a",{class:"header-anchor",href:"#如何在-fedora-上生成-epub-電子書","aria-label":"Permalink to “如何在 Fedora 上生成 EPUB 電子書”"},"​")],-1)),t[30]||(t[30]=o("p",null,[o("img",{src:"https://fedoramagazine.org/wp-content/uploads/2020/05/epub-how_to-816x345.png",alt:""})],-1)),t[31]||(t[31]=o("p",null,"在智能手機上閲讀內容正在變得越來越流行。每一部手機都有它自己的電子書閲讀器。可能你不知道，在 Fedora 創建你自己的電子書文件是非常容易的。",-1)),o("p",null,[t[1]||(t[1]=e("這篇文章展示了使用兩種不同的方法來創建一個 ",-1)),a(r,{href:"https://en.wikipedia.org/wiki/EPUB"},{default:p(()=>[...t[0]||(t[0]=[e("EPUB",-1)])]),_:1}),t[2]||(t[2]=e(" 文件。EPUB 格式是最流行的格式之一，並且被很多開源軟件所支持。",-1))]),t[32]||(t[32]=o("p",null,"絕大數的人們將會詢問 “在很容易創建 PDF 文件的情況下，為什麼要花費時間和精力來創建 EPUB 文件?” 答案是: “你曾經嘗試看過每次只能看到一張紙的一小部分的嗎?”為閲讀一個 PDF 文件，你不得不經常縮放和移動文檔，或者將其縮放到一個小尺寸來適合屏幕大小。在另一方面，EPUB 文件則被設計成可以適合很多不同的屏幕類型。",-1)),t[33]||(t[33]=o("h3",{id:"方法-1-ghostwriter-和-pandoc",tabindex:"-1"},[e("方法 1: ghostwriter 和 pandoc "),o("a",{class:"header-anchor",href:"#方法-1-ghostwriter-和-pandoc","aria-label":"Permalink to “方法 1: ghostwriter 和 pandoc”"},"​")],-1)),o("p",null,[t[5]||(t[5]=e("第一種方法創建一個速成版的電子書文件。它使用一個名為 ",-1)),a(r,{href:"https://github.com/wereturtle/ghostwriter"},{default:p(()=>[...t[3]||(t[3]=[e("ghostwriter",-1)])]),_:1}),t[6]||(t[6]=e(" 的 Markdown 編輯器，和一個名為 ",-1)),a(r,{href:"https://pandoc.org/"},{default:p(()=>[...t[4]||(t[4]=[e("pandoc",-1)])]),_:1}),t[7]||(t[7]=e(" 的命令列文檔轉換工具。",-1))]),t[34]||(t[34]=n('<p>你可以從軟件中心搜查和安裝它們，也可以從終端中安裝它們。如果你使用終端來安裝它們，運行這個命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install pandoc ghostwriter</span></span></code></pre></div>',2)),o("p",null,[t[9]||(t[9]=e("對於那些不知道 ",-1)),a(r,{href:"https://fedoramagazine.org/applications-for-writing-markdown/"},{default:p(()=>[...t[8]||(t[8]=[e("Markdown",-1)])]),_:1}),t[10]||(t[10]=e(" 是什麼的人們來説，在這裏有一個簡要的解釋：它是一個大約在 15 年前創建的簡單的標記語言。它使用簡單的語法來格式化純文本。Markdown 文件可以隨後轉換成很多其它文檔格式的文件。",-1))]),t[35]||(t[35]=n('<p><img src="https://fedoramagazine.org/wp-content/uploads/2020/05/ghostwriter-1024x640.jpg" alt="ghostwriter"></p><p>對於工具，ghostwriter 是一個跨平台的易於使用的 Markdown 編輯器。pandoc 是一個非常易於使用的文檔轉換工具，可以處理數百種不同的格式。</p><p>要創建你的電子書，打開 ghostwriter，開始編寫你的文檔。如果你以前使用過 Markdown，你可能習慣於在文檔的“標題 1”的前面放置一個 <code>#</code> 符號來作為標題。像這樣: <code># My Man Jeeves</code>。然而，pandoc 將不會識別其為標題，並將在你的電子書的頂部放置一個一個大的 “UNTITLED” 。相反地在你的標題前放置一個 <code>%</code> 來作為標題。例如，<code>% My Man Jeeves</code> 。章節應該被格式為“標題 2”，例如，<code>## Leave It to Jeeves</code>。如果你有子章節，使用“標題 3”（<code>###</code>）。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/05/ghostwriter-menu-1024x640.jpg" alt=""></p><p>在你的文檔完成後，單擊“文件 -&gt; 導出”（或按 <code>Ctrl+E</code> 鍵）。在對話框中，在幾個 Markdown 轉換器中進行選擇。如果這是你第一次使用 ghostwriter ，默認選擇的是 Sundown 轉換器。從對話框中，選擇 pandoc 。接下來單擊“導出”。現在你的 EPUB 文件已經創建好了。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/05/ghostwriter-export-1024x640.jpg" alt="ghostwriter 導出對話框"></p><p>注意: 如果你得到一個與 pandoc 有關的錯誤，關閉“智能排版”，並再試一次。</p><h3 id="方法-2-calibre" tabindex="-1">方法 2: calibre <a class="header-anchor" href="#方法-2-calibre" aria-label="Permalink to “方法 2: calibre”">​</a></h3><p>如果你想要一個更完美的電子書，那這就是你正在尋找的方法。它需要更多的步驟，但是是值得的。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/05/calibre-pre-1024x640.jpg" alt=""></p>',10)),o("p",null,[t[12]||(t[12]=e("首先，安裝一個名為 ",-1)),a(r,{href:"https://calibre-ebook.com/"},{default:p(()=>[...t[11]||(t[11]=[e("calibre",-1)])]),_:1}),t[13]||(t[13]=e(" 的應用程序。calibre 不僅僅是一個電子書閲讀器，它也是一個電子書管理器系統。你可以從軟件中心安裝它，也可以從終端安裝它：",-1))]),t[36]||(t[36]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install calibre</span></span></code></pre></div><p>在這個方法中，你可以在 LibreOffice、ghostwriter，或者其它你選擇的編輯器中編寫你的文檔。確保書籍的標題被格式為“標題 1”，章節被格式為“標題 2”，子章節被格式為“標題 3”。</p><p>接下來，導出你的文檔為一個 HTML 文件。</p><p>現在添加該文件到 calibre 。打開 calibre ，並單擊 “添加書籍”。calibre 會用幾秒鐘來添加文件。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/05/calibre-metadata-1024x640.jpg" alt=""></p><p>在文件導入後，通過單擊 “編輯元數據” 按鈕來編輯文件的元數據。在這裏你可以填寫書的標題和作者的姓名。你也可以上傳一個封面圖片（如果你有的話），或者 calibre 將為你生成一個封面。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/05/calibre-lookandfeel-1024x640.jpg" alt=""></p><p>接下來，單擊 “轉換書籍” 按鈕。在新的對話框中，選擇 “界面與外觀” 部分的 “佈局” 標籤頁。勾選 “刪除段間空行” 選項。這將更加嚴格地縮進每一段的內容。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/05/calibre-toc2-1024x640.jpg" alt=""></p><p>現在，設置目錄。選擇 “內容目錄” 部分。這裏有三個需要注意的選項: “一級目錄”、“二級目錄” 和 “三級目錄”。對於每一個選項點擊其末尾處的魔法棒按鈕。在新的對話框中，選擇應用於目錄表項的 HTML 標記。例如，為“一級目錄”選擇 “h1”。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/05/calibre-epub-output-1024x640.jpg" alt=""></p><p>接下來，告訴 calibre 包含內容目錄。選擇 “輸出 EPUB” 部分並勾選 “插入內聯目錄”。單擊“確定“ 創建 epub 文件。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/05/calibre-post-1024x640.jpg" alt=""></p><p>現在，你有了一個看起來很專業的電子書文件。</p><hr>',15)),o("p",null,[t[15]||(t[15]=e("via: ",-1)),a(r,{href:"https://fedoramagazine.org/how-to-generate-an-epub-file-on-fedora/"},{default:p(()=>[...t[14]||(t[14]=[e("https://fedoramagazine.org/how-to-generate-an-epub-file-on-fedora/",-1)])]),_:1})]),o("p",null,[t[20]||(t[20]=e("作者：",-1)),a(r,{href:"https://fedoramagazine.org/author/johnblood/"},{default:p(()=>[...t[16]||(t[16]=[e("John Paul Wohlscheid",-1)])]),_:1}),t[21]||(t[21]=e(" 選題：",-1)),a(r,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[17]||(t[17]=[e("lujun9972",-1)])]),_:1}),t[22]||(t[22]=e(" 譯者：",-1)),a(r,{href:"https://github.com/robsean"},{default:p(()=>[...t[18]||(t[18]=[e("robsean",-1)])]),_:1}),t[23]||(t[23]=e(" 校對：",-1)),a(r,{href:"https://github.com/wxy"},{default:p(()=>[...t[19]||(t[19]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[26]||(t[26]=e("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[24]||(t[24]=[e("LCTT",-1)])]),_:1}),t[27]||(t[27]=e(" 原創編譯，",-1)),a(r,{href:"https://linux.cn/"},{default:p(()=>[...t[25]||(t[25]=[e("Linux中國",-1)])]),_:1}),t[28]||(t[28]=e(" 榮譽推出",-1))])])}const x=i(g,[["render",u]]);export{P as __pageData,x as default};
